def normalize_and_validate_warehouse_names(apps, schema_editor):
    Warehouse = apps.get_model("warehouse", "Warehouse")
    for warehouse in Warehouse.objects.all().only("pk", "name"):
        normalized = warehouse.name.strip()
        if not normalized:
            raise RuntimeError(
                f"Warehouse #{warehouse.pk} has an empty display name"
            )
        if normalized != warehouse.name:
            Warehouse.objects.filter(pk=warehouse.pk).update(name=normalized)

    seen = set()
    duplicates = set()
    for name in Warehouse.objects.values_list("name", flat=True):
        normalized = name.casefold()
        if normalized in seen:
            duplicates.add(normalized)
        seen.add(normalized)
    if duplicates:
        raise RuntimeError(
            "Warehouse names must be unique ignoring case; duplicates: "
            + ", ".join(sorted(duplicates))
        )


def install_multi_warehouse_write_guards(apps, schema_editor):
    """Make legacy implicit writes fail closed once a product has >1 owner."""
