def restore_single_warehouse_write_guards(apps, schema_editor):
    if schema_editor.connection.vendor != "postgresql":
        return
    schema_editor.execute(
        """
        CREATE OR REPLACE FUNCTION public.asyl_product_wh_id(product_pk bigint)
        RETURNS bigint
        LANGUAGE plpgsql
        STABLE
        SET search_path = pg_catalog, public
        AS $$
        DECLARE
            result bigint;
        BEGIN
            SELECT warehouse_id INTO result
            FROM public.warehouse_stockitem
            WHERE product_id = product_pk;
            RETURN COALESCE(result, public.asyl_main_wh_id());
        END;
        $$;

        CREATE OR REPLACE FUNCTION public.wh_compat_product_event_warehouse()
        RETURNS trigger
        LANGUAGE plpgsql
        SET search_path = pg_catalog, public
        AS $$
        DECLARE
            expected_warehouse bigint;
        BEGIN
            expected_warehouse := public.asyl_product_wh_id(NEW.product_id);
            IF NEW.warehouse_id IS NULL THEN
                NEW.warehouse_id := expected_warehouse;
            ELSIF NEW.warehouse_id <> expected_warehouse THEN
                RAISE EXCEPTION
                    'product %% belongs to warehouse %%, not %%',
                    NEW.product_id, expected_warehouse, NEW.warehouse_id
                    USING ERRCODE = '23514';
            END IF;
            RETURN NEW;
        END;
        $$;
        """
    )


